/* @lc app=leetcode id=3625 lang=kotlin */ class Solution { fun g(a: Int, b: Int): Int = if (b == 0) Math.abs(a) else g(b, a % b) fun c2(x: Int): Long = x.toLong() * (x - 1) / 2 fun countTrapezoids(points: Array<IntArray>): Int = points.indices.flatMap { i -> (i + 1 until points.size).map { j -> (points[j][0] - points[i][0]).let { dx0 -> (points[j][1] - points[i][1]).let { dy0 -> g(dx0, dy0).let { gg -> (if (dx0 < 0 || (dx0 == 0 && dy0 < 0)) -1 else 1).let { sg -> (dx0 / gg * sg).let { dx -> (dy0 / gg * sg).let { dy -> ((dx + 2000) * 4001L + dy + 2000).let { sk -> ((dy * points[i][0] - dx * points[i][1]) + 5_000_000L).let { cc -> ((points[i][0] + points[j][0] + 2000) * 4001L + points[i][1] + points[j][1] + 2000).let { mk -> longArrayOf(sk, sk * 10_000_000L + cc, mk, mk * 20_000_000L + sk) } } } } } } } } } } }.let { segs -> (0..3).map { k -> segs.groupingBy { it[k] }.eachCount().values.sumOf { c2(it) } }.let { (a, b, c, d) -> ((a - b) - (c - d)).toInt() } } }